-- 000035_seed_move_commands.up.sql
-- M17-02: command 索引 move_commands の seed(非派生のみ・CHANGE-069 §2.1-b)
-- 本ファイルは cmd/seedgen が character_data/*.csv から生成した成果物(手編集しない)。
-- 非派生技(is_derived=false)のみ搭載。token_key は numpad 正規化済み(internal/moveindex が一元管理)。
-- 索引は広く持つ(必殺技・空中技も搭載)＝段階2 スコープへの絞り込みは消費者側(CHANGE-069 §1.5-6)。
-- 既存マイグレは非改変(新規連番で追加)。FK 依存順 characters→moves→move_commands。

-- ===== terry (48 commands) =====
INSERT INTO move_commands (move_id, character_id, token_key)
SELECT m.id, m.character_id, v.token_key
FROM moves m
JOIN characters c ON c.id = m.character_id
CROSS JOIN (
        SELECT 'sa2_power_geyser' AS code, '214214P' AS token_key
  UNION ALL SELECT 'crack_shoot_heavy', '214HK'
  UNION ALL SELECT 'burning_knuckle_heavy', '214HP'
  UNION ALL SELECT 'crack_shoot_od', '214K+K'
  UNION ALL SELECT 'crack_shoot_light', '214LK'
  UNION ALL SELECT 'quick_burn', '214LP'
  UNION ALL SELECT 'quick_burn_od', '214LP+MP'
  UNION ALL SELECT 'crack_shoot_medium', '214MK'
  UNION ALL SELECT 'burning_knuckle_medium', '214MP'
  UNION ALL SELECT 'burning_knuckle_od', '214P+P'
  UNION ALL SELECT 'sa1_buster_wolf', '236236K'
  UNION ALL SELECT 'sa3_rising_fang', '236236P'
  UNION ALL SELECT 'ca_rising_fang', '236236P'
  UNION ALL SELECT 'power_charge_heavy', '236HK'
  UNION ALL SELECT 'round_wave', '236HP'
  UNION ALL SELECT 'power_charge_od', '236K+K'
  UNION ALL SELECT 'power_charge_light', '236LK'
  UNION ALL SELECT 'power_wave_light', '236LP'
  UNION ALL SELECT 'power_charge_medium', '236MK'
  UNION ALL SELECT 'power_wave_medium', '236MP'
  UNION ALL SELECT 'power_wave_od', '236P+P'
  UNION ALL SELECT 'crouching_heavy_kick', '2HK'
  UNION ALL SELECT 'crouching_heavy_punch', '2HP'
  UNION ALL SELECT 'crouching_light_kick', '2LK'
  UNION ALL SELECT 'crouching_light_punch', '2LP'
  UNION ALL SELECT 'crouching_medium_kick', '2MK'
  UNION ALL SELECT 'crouching_medium_punch', '2MP'
  UNION ALL SELECT 'throw_back', '4LP+LK'
  UNION ALL SELECT 'throw_forward', '5/6LP+LK'
  UNION ALL SELECT 'rising_tackle_heavy', '623HP'
  UNION ALL SELECT 'rising_tackle_light', '623LP'
  UNION ALL SELECT 'rising_tackle_medium', '623MP'
  UNION ALL SELECT 'rising_tackle_od', '623P+P'
  UNION ALL SELECT 'hammer_punch', '6HP'
  UNION ALL SELECT 'standing_heavy_kick', 'HK'
  UNION ALL SELECT 'jumping_heavy_kick', 'HK'
  UNION ALL SELECT 'standing_heavy_punch', 'HP'
  UNION ALL SELECT 'jumping_heavy_punch', 'HP'
  UNION ALL SELECT 'drive_impact', 'HP+HK'
  UNION ALL SELECT 'standing_light_kick', 'LK'
  UNION ALL SELECT 'jumping_light_kick', 'LK'
  UNION ALL SELECT 'standing_light_punch', 'LP'
  UNION ALL SELECT 'jumping_light_punch', 'LP'
  UNION ALL SELECT 'standing_medium_kick', 'MK'
  UNION ALL SELECT 'jumping_medium_kick', 'MK'
  UNION ALL SELECT 'standing_medium_punch', 'MP'
  UNION ALL SELECT 'jumping_medium_punch', 'MP'
  UNION ALL SELECT 'drive_parry', 'MP+MK'
) AS v
WHERE c.code = 'terry' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6') AND m.code = v.code;

